CREATE TABLE gifts_account_write_gates(account_id uuid PRIMARY KEY,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),erased_at timestamptz(3),request_id uuid,CHECK((erased_at IS NULL)=(request_id IS NULL)));
CREATE TABLE gift_catalog_items(id text PRIMARY KEY,version integer NOT NULL CHECK(version>0),snapshot jsonb NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES gifts_account_write_gates(account_id),reason text NOT NULL CHECK(reason IN('trial_grant','gift_debit','gift_reversal')),source_id text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),policy_version text NOT NULL,original_transaction_id uuid,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_id,id),UNIQUE(account_id,reason,source_id),FOREIGN KEY(account_id,original_transaction_id) REFERENCES ledger_transactions(account_id,id),CHECK((reason='gift_reversal')=(original_transaction_id IS NOT NULL)));
CREATE TABLE asset_lots(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES gifts_account_write_gates(account_id),asset_type text NOT NULL CHECK(asset_type IN('postage','inventory','voucher')),asset_id text NOT NULL,source text NOT NULL CHECK(source='trial'),balance_units integer NOT NULL CHECK(balance_units>=0),issued_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz(3),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),policy_version text NOT NULL,issuance_transaction_id uuid NOT NULL,UNIQUE(account_id,id),FOREIGN KEY(account_id,issuance_transaction_id) REFERENCES ledger_transactions(account_id,id),CHECK(expires_at IS NULL OR expires_at>issued_at));
CREATE TABLE ledger_entries(account_id uuid NOT NULL,transaction_id uuid NOT NULL,line_no integer NOT NULL CHECK(line_no>0),lot_id uuid NOT NULL,direction text NOT NULL CHECK(direction IN('credit','debit')),units integer NOT NULL CHECK(units>0),PRIMARY KEY(transaction_id,line_no),FOREIGN KEY(account_id,transaction_id) REFERENCES ledger_transactions(account_id,id),FOREIGN KEY(account_id,lot_id) REFERENCES asset_lots(account_id,id));
CREATE TABLE gift_deliveries(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES gifts_account_write_gates(account_id),acceptance_key uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),person_id uuid NOT NULL,conversation_id uuid NOT NULL,person_snapshot jsonb NOT NULL,gift_snapshot jsonb NOT NULL,quantity smallint NOT NULL CHECK(quantity BETWEEN 1 AND 99),note text NOT NULL CHECK(char_length(note)<=120),source text NOT NULL CHECK(source IN('trial','inventory','voucher')),cost integer NOT NULL CHECK(cost>=0),status text NOT NULL DEFAULT 'in_transit' CHECK(status IN('in_transit','arrived','delivery_failed')),version integer NOT NULL DEFAULT 1 CHECK(version>0),account_access_version integer NOT NULL CHECK(account_access_version>0),gift_authorization_version integer NOT NULL CHECK(gift_authorization_version>0),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),scheduled_arrival_at timestamptz(3) NOT NULL,arrived_at timestamptz(3),failed_at timestamptz(3),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),debit_transaction_id uuid,reversal_transaction_id uuid,failure_code text,UNIQUE(account_id,id),UNIQUE(account_id,acceptance_key),FOREIGN KEY(account_id,debit_transaction_id) REFERENCES ledger_transactions(account_id,id),FOREIGN KEY(account_id,reversal_transaction_id) REFERENCES ledger_transactions(account_id,id),CHECK(scheduled_arrival_at>=created_at),CHECK((status='arrived')=(arrived_at IS NOT NULL)),CHECK((status='delivery_failed')=(failed_at IS NOT NULL)),CHECK(reversal_transaction_id IS NULL OR(status='delivery_failed' AND debit_transaction_id IS NOT NULL)));
CREATE INDEX gift_deliveries_account ON gift_deliveries(account_id,created_at,id);
CREATE TABLE gifts_jobs(id uuid PRIMARY KEY,account_id uuid NOT NULL,delivery_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('deliver','project')),delivery_version integer NOT NULL CHECK(delivery_version>0),state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','failed','succeeded','blocked')),version integer NOT NULL DEFAULT 1 CHECK(version>0),attempt_id uuid,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),lease_until timestamptz(3),retry_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz(3),failure_code text,UNIQUE(account_id,delivery_id,kind,delivery_version),FOREIGN KEY(account_id,delivery_id) REFERENCES gift_deliveries(account_id,id),CHECK((state='running')=(attempt_id IS NOT NULL AND lease_until IS NOT NULL)),CHECK(state NOT IN('succeeded','blocked') OR finished_at IS NOT NULL));
CREATE TABLE outbox_events(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES gifts_account_write_gates(account_id),type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version integer NOT NULL CHECK(aggregate_version>0),payload jsonb NOT NULL,occurred_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_id,type,aggregate_id,aggregate_version));
CREATE TABLE gifts_erase_receipts(account_id uuid PRIMARY KEY REFERENCES gifts_account_write_gates(account_id),request_id uuid NOT NULL UNIQUE,erased_at timestamptz(3) NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION gifts_write_gate() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE fenced timestamptz;BEGIN
 IF TG_OP='UPDATE' AND NEW.account_id<>OLD.account_id THEN RAISE EXCEPTION 'immutable account' USING ERRCODE='42501';END IF;
 SELECT erased_at INTO fenced FROM gifts_account_write_gates WHERE account_id=NEW.account_id FOR SHARE;
 IF NOT FOUND OR fenced IS NOT NULL THEN RAISE EXCEPTION 'gifts account unavailable' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
CREATE TRIGGER gifts_lots_gate BEFORE INSERT OR UPDATE ON asset_lots FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE TRIGGER gifts_transactions_gate BEFORE INSERT ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE TRIGGER gifts_entries_gate BEFORE INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE TRIGGER gifts_deliveries_gate BEFORE INSERT OR UPDATE ON gift_deliveries FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE TRIGGER gifts_jobs_gate BEFORE INSERT OR UPDATE ON gifts_jobs FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE TRIGGER gifts_outbox_gate BEFORE INSERT ON outbox_events FOR EACH ROW EXECUTE FUNCTION gifts_write_gate();
CREATE FUNCTION immutable_gifts_ledger() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM gifts_account_write_gates WHERE account_id=OLD.account_id AND erased_at IS NOT NULL) THEN RETURN OLD;END IF;
 RAISE EXCEPTION 'ledger is append only outside account erasure' USING ERRCODE='42501';END$$;
CREATE TRIGGER immutable_gifts_transactions BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION immutable_gifts_ledger();
CREATE TRIGGER immutable_gifts_entries BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_gifts_ledger();
